class Solution:
    def minimumChanges(self, s: str, k: int) -> int:
        n = len(s)
        cost = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(i + 1, n):
                L = j - i + 1
                best = float('inf')
                for d in range(1, L):
                    if L % d: continue
                    m = L // d
                    c = 0
                    for r in range(d):
                        for t in range(m // 2):
                            if s[i + r + t * d] != s[i + r + (m - 1 - t) * d]:
                                c += 1
                    best = min(best, c)
                cost[i][j] = best
        INF = float('inf')
        dp = [[INF] * (n + 1) for _ in range(k + 1)]
        dp[0][0] = 0
        for c in range(1, k + 1):
            for j in range(c, n + 1):
                for i in range(c - 1, j):
                    if dp[c-1][i] < INF:
                        dp[c][j] = min(dp[c][j], dp[c-1][i] + cost[i][j-1])
        return dp[k][n]

