class Solution {
public:
    int minimumChanges(string s, int k) {
        int n = s.size();
        vector<vector<int>> cost(n, vector<int>(n));
        for (int i = 0; i < n; ++i)
            for (int j = i + 1; j < n; ++j) {
                int L = j - i + 1, best = INT_MAX;
                for (int d = 1; d < L; ++d) {
                    if (L % d) continue;
                    int m = L / d, c = 0;
                    for (int r = 0; r < d; ++r)
                        for (int t = 0; t < m / 2; ++t)
                            if (s[i + r + t * d] != s[i + r + (m - 1 - t) * d]) ++c;
                    best = min(best, c);
                }
                cost[i][j] = best;
            }
        const int INF = INT_MAX / 2;
        vector<vector<int>> dp(k + 1, vector<int>(n + 1, INF));
        dp[0][0] = 0;
        for (int c = 1; c <= k; ++c)
            for (int j = c; j <= n; ++j)
                for (int i = c - 1; i < j; ++i)
                    dp[c][j] = min(dp[c][j], dp[c-1][i] + cost[i][j-1]);
        return dp[k][n];
    }
};

