class Solution {
    public int minimumChanges(String s, int k) {
        int n = s.length();
        int[][] cost = new int[n][n];
        for (int i = 0; i < n; ++i)
            for (int j = i + 1; j < n; ++j) {
                int L = j - i + 1, best = Integer.MAX_VALUE;
                for (int d = 1; d < L; ++d) {
                    if (L % d != 0) continue;
                    int m = L / d, c = 0;
                    for (int r = 0; r < d; ++r)
                        for (int t = 0; t < m / 2; ++t)
                            if (s.charAt(i + r + t * d) != s.charAt(i + r + (m - 1 - t) * d)) ++c;
                    best = Math.min(best, c);
                }
                cost[i][j] = best;
            }
        int INF = Integer.MAX_VALUE / 2;
        int[][] dp = new int[k + 1][n + 1];
        for (int[] row : dp) java.util.Arrays.fill(row, INF);
        dp[0][0] = 0;
        for (int c = 1; c <= k; ++c)
            for (int j = c; j <= n; ++j)
                for (int i = c - 1; i < j; ++i)
                    dp[c][j] = Math.min(dp[c][j], dp[c-1][i] + cost[i][j-1]);
        return dp[k][n];
    }
}

