var minimumChanges = function(s, k) {
    const n = s.length;
    const cost = Array.from({length: n}, () => new Array(n).fill(0));
    for (let i = 0; i < n; ++i)
        for (let j = i + 1; j < n; ++j) {
            const L = j - i + 1;
            let best = Infinity;
            for (let d = 1; d < L; ++d) {
                if (L % d) continue;
                const m = L / d;
                let c = 0;
                for (let r = 0; r < d; ++r)
                    for (let t = 0; t < Math.floor(m / 2); ++t)
                        if (s[i + r + t * d] !== s[i + r + (m - 1 - t) * d]) ++c;
                best = Math.min(best, c);
            }
            cost[i][j] = best;
        }
    const INF = Infinity;
    const dp = Array.from({length: k + 1}, () => new Array(n + 1).fill(INF));
    dp[0][0] = 0;
    for (let c = 1; c <= k; ++c)
        for (let j = c; j <= n; ++j)
            for (let i = c - 1; i < j; ++i)
                dp[c][j] = Math.min(dp[c][j], dp[c-1][i] + cost[i][j-1]);
    return dp[k][n];
};
